use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs,path::Path,process::Command};
const R:&str="/home/ubuntu/src/zopro-perf-work/phase-search-c7a178";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn save(p:impl AsRef<Path>,v:Value){assert!(!p.as_ref().exists());fs::write(p,serde_json::to_vec_pretty(&v).unwrap()).unwrap()}
fn main(){let r=Path::new(R);let finalrun=read(r.join("final-run/result.json"));assert_eq!(finalrun["status"],"complete");let pins=read(r.join("final-pins.json"));for(p,h)in pins.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}let local=read(r.join("local-review.json"));assert_eq!(local["passed"],true);assert_eq!(local["canonical_count"],55028);
let image=Command::new("docker").args(["image","inspect","zopro-phase-search-c7a:final","--format","{{.Id}}"] ).output().unwrap();assert!(image.status.success());let image=String::from_utf8(image.stdout).unwrap().trim().to_string();assert!(image.starts_with("sha256:"));let date=Command::new("date").args(["-u","+%Y%m%d-%H%M%S"]).output().unwrap();assert!(date.status.success());let stamp=String::from_utf8(date.stdout).unwrap().trim().to_string();let id=format!("phase-search-c7a-{stamp}");let tag=format!("558215002830.dkr.ecr.eu-north-1.amazonaws.com/zolana-prover:bench-{id}");assert!(Command::new("docker").args(["tag",&image,&tag]).status().unwrap().success());assert!(!r.join("run-id.txt").exists());fs::write(r.join("run-id.txt"),format!("{id}\n")).unwrap();
let im=json!({"status":"local package ready; cloud unrun","image_tag":tag,"local_image_id":image,"local_gnark_proofs":4,"local_preflight_sdk":16,"local_proof_ledger":55028,"accepted_sdk_sha256":"b646c7b8c1d8a26a0db45fb3f67c453dd616bd9f02e25c36192721ae02855abe","retained_candidate_sdk_sha256":"1f1f432a7399f82aa98226e7e5c166da08150921e1148eb359a06307fd232579","target_blocks":9,"target_latency_exports":120,"target_profile_exports":4,"target_exports":124,"target_SDK_requests":17596,"target_final_ledger":55152});save(r.join("image-manifest.json"),im.clone());save(r.join("image-manifest-prepublish.json"),im);
let mut out:BTreeMap<String,String>=serde_json::from_value(pins).unwrap();for f in["transport-review.rs","transport-review","profile-protocol.md","stage.rs","run-id.txt","image-manifest-prepublish.json","final-plan.json","preflight-plan.json"]{let p=r.join(f);out.insert(p.display().to_string(),hash(p));}save(r.join("prepared-pins.json"),json!(out));
save(r.join("checkpoint.json"),json!({"status":"target package ready; awaiting valid AWS credentials","goal":"active/unmet 0/8","production_changed":false,"local_preflight_passed":true,"target_measured":false,"canonical_count":55028,"canonical_path":r.join("proof-sha256-after-preflight.json"),"canonical_sha256":local["canonical_sha256"],"live_handles":[],"AWS_resources_created":false,"run_id":id,"next":"validate prepared pins, cloud publish/launch with fresh credential/ownership/ingress guards; poll sole SSM measure handle through latency+profile; retrieve/verify/cleanup"}));println!("Prepared finalimage{image};124targetexports/17596SDKcalls frozen, none run");}
